// Process search results and format for AI Agent response
const results = $input.all();

if (!results || results.length === 0) {
  return {
    json: {
      found_knowledge: false,
      content: '',
      sources: [],
      message: 'I don\'t have information about that in my knowledge base. Please contact our team at (970) 446-8995 for assistance.'
    }
  };
}

// Extract and combine relevant content
let combinedContent = '';
let sources = [];

for (const item of results) {
  if (item.json.pageContent || item.json.content) {
    const content = item.json.pageContent || item.json.content;
    const title = item.json.metadata?.title || 'Knowledge Item';

    combinedContent += content + '\n\n';
    sources.push({
      title: title,
      content: content.substring(0, 200) + '...',
      similarity: item.json.metadata?.similarity || 0
    });
  }
}

return {
  json: {
    found_knowledge: combinedContent.length > 0,
    content: combinedContent.trim(),
    sources: sources,
    query: $('Prepare Search Query').first().json.query,
    session_id: $('Prepare Search Query').first().json.session_id,
    message: combinedContent.length > 0 ? 'Found relevant information' : 'No relevant information found'
  }
};
